15	/// Trait for command implementations.
16	///
17	/// Each CLI subcommand implements this trait to provide its execution logic.
18	pub trait Command {
19	    /// Execute the command.
20	    ///
21	    /// # Arguments
22	    ///
23	    /// * `ui` - User interface for displaying output and prompts
24	    ///
25	    /// # Returns
26	    ///
27	    /// A [`CommandResult`] indicating success/failure and exit code.
28	    fn execute(&self, ui: &mut dyn UserInterface) -> Result<CommandResult>;
29	}
