31	/// Result of command execution.
32	#[derive(Debug)]
33	pub struct CommandResult {
34	    /// Whether the command succeeded.
35	    pub success: bool,
36	
37	    /// Exit code to use (0 for success, non-zero for failure).
38	    pub exit_code: i32,
39	}
40	
41	impl CommandResult {
42	    /// Create a successful result.
43	    pub fn success() -> Self {
44	        Self {
45	            success: true,
46	            exit_code: 0,
47	        }
48	    }
49	
50	    /// Create a failure result.
51	    pub fn failure(exit_code: i32) -> Self {
52	        Self {
53	            success: false,
54	            exit_code,
55	        }
56	    }
57	}
