40	/// Execute a step with retry and interactive recovery.
41	///
42	/// This handles the full execution lifecycle: spinner display, output capture,
43	/// auto-retries, and the interactive recovery menu (retry/fix/shell/skip/abort).
44	#[allow(clippy::too_many_arguments)]
45	pub(super) fn execute_step_with_recovery(
46	    step: &ResolvedStep,
47	    step_name: &str,
48	    step_number: &str,
49	    step_indent: usize,
50	    project_root: &Path,
51	    context: &InterpolationContext,
52	    base_env: &HashMap<String, String>,
53	    process_env: &HashMap<String, String>,
54	    needs_force: bool,
55	    dry_run: bool,
56	    interactive: bool,
57	    step_ctx: &StepContext<'_>,
58	    diagnostic_funnel: bool,
59	    workflow_state: &diagnostic::WorkflowState<'_>,
60	    ui: &mut dyn UserInterface,
61	    step_display: &mut dyn StepDisplay,
62	    event_bus: &mut EventBus,
63	) -> Result<StepExecutionResult> {
64	    let mut retry_count: u32 = 0;
65	    let mut fix_history: HashSet<String> = HashSet::new();
66	    let mut skipped_by_user = false;
67	    let mut aborted = false;
68	    #[allow(unused_assignments)]
69	    let mut final_result: Option<StepResult> = None;
70	
71	    // Outer loop: step execution (retry/fix re-enter here)
72	    'step_execution: loop {
73	        // Fresh spinner per attempt — hide command text for sensitive steps
74	        let display_command = if step.behavior.sensitive {
75	            "[SENSITIVE]".to_string()
76	        } else {
77	            step.execution.command.clone()
78	        };
79	        // Mount the transient region with the spinner. The step display
80	        // owns the live-output ring buffer.
81	        step_display.start_running(&display_command);
82	        let output_mode = step_display.output_mode();
83	        let output_callback: Option<OutputCallback> = step_display.live_output_callback();
84	
85	        let exec_options = ExecutionOptions {
86	            force: needs_force,
87	            dry_run,
88	            capture_output: output_callback.is_none(),
89	            ..Default::default()
90	        };
91	        let _ = step_number;
92	
93	        let step_start = Instant::now();
94	        let result = match execute_step(
95	            step,
96	            project_root,
97	            context,
98	            base_env,
99	            process_env,
100	            &exec_options,
101	            output_callback,
102	        ) {
103	            Ok(result) => result,
104	            Err(e) => {
105	                warn!("Step '{}' errored: {}", step_name, e);
106	                StepResult::failure(step_name, step_start.elapsed(), e.to_string(), None)
107	            }
108	        };
109	
110	        // Emit StepOutput events for captured output
111	        if let Some(ref output) = result.output {
112	            for line in output.lines() {
113	                event_bus.emit(&BivvyEvent::StepOutput {
114	                    name: step_name.to_string(),
115	                    stream: "stdout".to_string(),
116	                    line: line.to_string(),
117	                });
118	            }
119	        }
120	
121	        let duration_str = format_duration(result.duration);
122	
123	        match result.status() {
124	            StepStatus::Completed => {
125	                let detail = if retry_count > 0 {
126	                    Some(format!("succeeded on retry (attempt {})", retry_count + 1))
127	                } else {
128	                    None
129	                };
130	                // Clear the transient region and write the final result
131	                // line into scrollback. The label is derived from the
132	                // status enum inside `finish`.
133	                step_display.finish(
134	                    StepStatus::Completed,
135	                    Some(result.duration),
136	                    detail.as_deref(),
137	                );
138	                let mut r = result;
139	                r.recovery_detail = detail;
140	                final_result = Some(r);
141	                break 'step_execution;
142	            }
143	            StepStatus::Skipped => {
144	                step_display.finish(StepStatus::Skipped, None, None);
145	                final_result = Some(result);
146	                break 'step_execution;
147	            }
148	            StepStatus::Failed => {
149	                step_display.finish(StepStatus::Failed, Some(result.duration), None);
150	                let _ = duration_str;

