156	/// Execute a shell command.
157	pub fn execute(command: &str, options: &CommandOptions) -> Result<CommandResult> {
158	    let start = Instant::now();
159	
160	    let shell = detect_shell();
161	    let shell_flag = shell_flag(&shell);
162	
163	    let mut cmd = Command::new(&shell);
164	    cmd.arg(shell_flag);
165	    cmd.arg(command);
166	
167	    // Run the child in bivvy's own process group. An earlier attempt
168	    // moved the child into its own group via `Command::process_group(0)`
169	    // (commit a19bdae) to keep zsh's job control from reclaiming the
170	    // foreground when the child exits. That fix exposed a worse hang:
171	    // commands whose process trees touch the controlling terminal
172	    // (notably `cargo test`, where libtest or its child binaries make
173	    // a transient `tcsetpgrp` call and then the temporary foreground
174	    // pgid dies) leave every member of the now-background child group
175	    // permanently SIGTTOU-stopped. Sharing bivvy's pgroup keeps the
176	    // child in the foreground for the duration of its run, and the
177	    // `claim_foreground` call after wait still re-asserts ownership
178	    // for the zsh edge case.
179	
180	    // Set working directory
181	    if let Some(cwd) = &options.cwd {
182	        cmd.current_dir(cwd);
183	    }
184	
185	    // Set environment
186	    for (key, value) in &options.env {
187	        cmd.env(key, value);
188	    }
189	
190	    // Configure stdio
191	    if options.stdin_null {
192	        cmd.stdin(Stdio::null());
193	    }
194	
195	    if options.capture_stdout {
196	        cmd.stdout(Stdio::piped());
197	    } else {
198	        cmd.stdout(Stdio::inherit());
199	    }
200	
201	    if options.capture_stderr {
202	        cmd.stderr(Stdio::piped());
203	    } else {
204	        cmd.stderr(Stdio::inherit());
205	    }
206	
207	    // Execute
208	    let output = cmd.output().map_err(|_| BivvyError::CommandFailed {
209	        command: command.to_string(),
210	        code: None,
211	    })?;
212	
213	    // Re-claim foreground after the child's process group exits.
214	    #[cfg(unix)]
215	    claim_foreground();
216	
217	    let duration = start.elapsed();
218	
219	    let stdout = if options.capture_stdout {
220	        String::from_utf8_lossy(&output.stdout).to_string()
221	    } else {
222	        String::new()
223	    };
224	
225	    let stderr = if options.capture_stderr {
226	        String::from_utf8_lossy(&output.stderr).to_string()
227	    } else {
228	        String::new()
229	    };
230	
231	    if output.status.success() {
232	        Ok(CommandResult::success(stdout, stderr, duration))
233	    } else {
234	        Ok(CommandResult::failure(
235	            output.status.code(),
236	            stdout,
237	            stderr,
238	            duration,
239	        ))
240	    }
241	}
